 readonly GameVersions versions=new();
 static bool VersionCheckDue(VersionRecord v)=>v.NextReleaseCheckAt.HasValue?DateTimeOffset.UtcNow>=v.NextReleaseCheckAt.Value:!v.CheckedAt.HasValue||DateTimeOffset.UtcNow-v.CheckedAt.Value>=TimeSpan.FromDays(1);
 static string VersionKey(Game g)=>string.Join("|",g.SteamId,g.TrackPath,g.LaunchPath,g.VersionInfo.Mode,g.VersionInfo.ManualVersion,g.VersionInfo.ManualLatest,g.VersionInfo.ManifestPath,g.VersionInfo.EvidencePath,g.VersionInfo.AutoCheck,g.VersionInfo.ReleaseAppId,g.VersionInfo.GitHubRepository,g.VersionInfo.ConfirmedReleaseSource,g.VersionInfo.InstalledConfirmed,g.VersionInfo.CompareBuildDate,g.VersionInfo.ConfirmedBuildDate);
 bool versionChecksRunning;
 async Task CheckConfiguredVersions(){if(versionChecksRunning||demo||!library.Online)return;versionChecksRunning=true;bool dirty=false;int changed=0;try{
  foreach(var game in library.Games.Where(g=>!g.Removed&&!g.Archived&&!g.IsTool&&(g.VersionInfo.AutoCheck||library.CheckUpdateDates)&&(g.VersionInfo.AutoCheck?VersionCheckDue(g.VersionInfo):!g.VersionInfo.NextReleaseCheckAt.HasValue||DateTimeOffset.UtcNow>=g.VersionInfo.NextReleaseCheckAt.Value)).ToArray()){
   await Task.Delay(750,lifetime.Token);if(!IsActive||!IsEnabled||sessions.Any(s=>s.Status=="Playing"))break;string key=VersionKey(game);var snapshot=JsonSerializer.Deserialize<Game>(JsonSerializer.Serialize(game,Store.Json),Store.Json)!;
   var info=await (game.VersionInfo.AutoCheck?versions.Check(snapshot,root,library.Online,lifetime.Token):versions.CheckUpdates(snapshot,root,library.Online,lifetime.Token));if(game.VersionInfo.AutoCheck&&library.CheckUpdateDates){snapshot.VersionInfo=info;info=await versions.CheckUpdates(snapshot,root,library.Online,lifetime.Token);}if(lifetime.IsCancellationRequested)return;if(VersionKey(game)!=key||game.Removed||game.Archived||game.IsTool)continue;game.VersionInfo=info;if(info.AppId>0&&info.InstalledBuild.Length>0)game.SteamId=info.AppId;dirty=true;if(++changed%10==0){Store.Save(root,library);dirty=false;}
  }
 }catch(OperationCanceledException){}catch(Exception e){if(!lifetime.IsCancellationRequested)status.Text="Version checks paused: "+e.Message;}
 finally{versionChecksRunning=false;if(dirty){try{Store.Save(root,library);}catch(Exception e){if(!lifetime.IsCancellationRequested)status.Text="Could not save version evidence: "+e.Message;}}if(changed>0&&!lifetime.IsCancellationRequested&&IsEnabled)Render();}}


