 static string VersionDescription(VersionRecord v)=>v.Status+"\n\nInstalled: "+(v.Installed.Length>0?v.Installed:"Unknown")+"\nInstalled source: "+v.Source+"\nLatest release: "+(v.ManualLatest.Length>0?v.ManualLatest+" (your note)":v.LatestVersion.Length>0?v.LatestVersion:"Unknown")+"\nRelease source: "+v.ReleaseSourceKey+(v.LatestBuild.Length>0?"\nLatest reported Steam build: "+v.LatestBuild+" · "+v.Branch:"")+"\nLocal check: "+(v.ObservedAt?.LocalDateTime.ToString("dd MMM yyyy HH:mm")??"Not checked")+"\nOnline evidence: "+((v.ReleaseCheckedAt??v.RemoteCheckedAt)?.LocalDateTime.ToString("dd MMM yyyy HH:mm")??"Not available");
